local HorseHarnessMaker = {}
local PRODUCTS = {
    iron_harness = { name = "Železni jermen za konjsko vprego", ironCost = 2, woodCost = 1, leatherCost = 4, time = 6, cost = 240, prestige = 3, happiness = 2, description = "Železni jermen za osnovno vprego." },
    bronze_harness = { name = "Bronast jermen za konjsko vprego", bronzeCost = 2, ironCost = 1, woodCost = 1, leatherCost = 4, time = 8, cost = 580, prestige = 5, happiness = 3, description = "Bronast jermen za lahke vozove." },
    silver_harness = { name = "Srebrni jermen za konjsko vprego", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 4, time = 12, cost = 1400, prestige = 10, happiness = 4, description = "Srebrni jermen za plemiške vozove." },
    gilded_harness = { name = "Pozlačeni jermen za konjsko vprego", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 1, leatherCost = 4, time = 16, cost = 3000, prestige = 20, happiness = 5, description = "Pozlačeni jermen za dvorne vozove." },
    jewel_set_harness = { name = "Draguljasti jermen za konjsko vprego", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 4, time = 20, cost = 6300, prestige = 36, happiness = 7, description = "Draguljasti jermen za kraljeve vozove." },
    royal_sovereign_harness = { name = "Kraljevski suvereni jermen za konjsko vprego", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 5, time = 27, cost = 13000, prestige = 70, happiness = 13, description = "Suvereni jermen z biseri za krono." },
}
local BUILDINGS = {
    harness_workshop = { name = "Jermenska delavnica", cost = { gold = 395, wood = 185, stone = 145, iron = 8 }, upkeep = 7, qualityBonus = 5 },
    harness_house = { name = "Jermenska hiša", cost = { gold = 1340, wood = 365, stone = 285, silver = 8, iron = 8 }, upkeep = 29, qualityBonus = 18 },
    master_harness_atelier = { name = "Mojstrski jermenski atelje", cost = { gold = 3280, wood = 425, stone = 550, silver = 39, gold = 8 }, upkeep = 77, qualityBonus = 30 },
    sovereign_harness_palace = { name = "Suverena jermenska palača", cost = { gold = 14300, wood = 705, stone = 910, gold = 91, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
HorseHarnessMaker.ironStock = 12; HorseHarnessMaker.bronzeStock = 10; HorseHarnessMaker.woodStock = 14; HorseHarnessMaker.leatherStock = 16; HorseHarnessMaker.silverStock = 8; HorseHarnessMaker.goldStock = 6; HorseHarnessMaker.jewelStock = 4; HorseHarnessMaker.pearlStock = 4
HorseHarnessMaker.productStock = {}; HorseHarnessMaker.buildings = {}; HorseHarnessMaker.maker = nil; HorseHarnessMaker.activeMaking = {}; HorseHarnessMaker.totalProducts = 0; HorseHarnessMaker.dayTimer = 0
function HorseHarnessMaker.init() HorseHarnessMaker.ironStock=12; HorseHarnessMaker.bronzeStock=10; HorseHarnessMaker.woodStock=14; HorseHarnessMaker.leatherStock=16; HorseHarnessMaker.silverStock=8; HorseHarnessMaker.goldStock=6; HorseHarnessMaker.jewelStock=4; HorseHarnessMaker.pearlStock=4; HorseHarnessMaker.productStock={}; HorseHarnessMaker.buildings={}; HorseHarnessMaker.maker=nil; HorseHarnessMaker.activeMaking={}; HorseHarnessMaker.totalProducts=0; HorseHarnessMaker.dayTimer=0; print("[HorseHarnessMaker] Royal Horse Harness Maker System initialized (6 products, 4 buildings)") end
function HorseHarnessMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HorseHarnessMaker.maker={name=n or ("Jermenar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jermenar najet: %s (spretnost: %d)",HorseHarnessMaker.maker.name,s),"success") end; return true end
function HorseHarnessMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HorseHarnessMaker.build(id) local ok,e=HorseHarnessMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HorseHarnessMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HorseHarnessMaker.getQualityBonus() local b=0; for _,bd in ipairs(HorseHarnessMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HorseHarnessMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HorseHarnessMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HorseHarnessMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HorseHarnessMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HorseHarnessMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HorseHarnessMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HorseHarnessMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HorseHarnessMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HorseHarnessMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HorseHarnessMaker.buildings==0 then return false,"Potrebna jermenska delavnica" end; if not HorseHarnessMaker.maker then return false,"Potreben jermenar" end; return true end
function HorseHarnessMaker.make(pt,qty) qty=qty or 1; local ok,e=HorseHarnessMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HorseHarnessMaker.ironStock=HorseHarnessMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HorseHarnessMaker.bronzeStock=HorseHarnessMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HorseHarnessMaker.woodStock=HorseHarnessMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HorseHarnessMaker.leatherStock=HorseHarnessMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HorseHarnessMaker.silverStock=HorseHarnessMaker.silverStock-d.silverCost*qty end; if d.goldCost then HorseHarnessMaker.goldStock=HorseHarnessMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HorseHarnessMaker.jewelStock=HorseHarnessMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HorseHarnessMaker.pearlStock=HorseHarnessMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HorseHarnessMaker.maker then t=math.max(1,t-math.floor(HorseHarnessMaker.maker.skill/13)) end; table.insert(HorseHarnessMaker.activeMaking,{id="harness_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HorseHarnessMaker.completeMaking(m) local q=1.0+(HorseHarnessMaker.getQualityBonus()/100); if HorseHarnessMaker.maker then q=q+(HorseHarnessMaker.maker.skill/140) end; q=math.min(2.5,q); HorseHarnessMaker.productStock[m.productType]=(HorseHarnessMaker.productStock[m.productType] or 0)+m.quantity; HorseHarnessMaker.totalProducts=HorseHarnessMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HorseHarnessMaker.maker then HorseHarnessMaker.maker.itemsMade=HorseHarnessMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HorseHarnessMaker.maker.skill=math.min(100,HorseHarnessMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jermen izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"harness.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HorseHarnessMaker.update(dt) if not _G.state then return end; HorseHarnessMaker.dayTimer=HorseHarnessMaker.dayTimer+dt; if HorseHarnessMaker.dayTimer>=30 then HorseHarnessMaker.dayTimer=0; for i=#HorseHarnessMaker.activeMaking,1,-1 do local m=HorseHarnessMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HorseHarnessMaker.completeMaking(m); table.remove(HorseHarnessMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HorseHarnessMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HorseHarnessMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HorseHarnessMaker.getStats() return {ironStock=HorseHarnessMaker.ironStock,bronzeStock=HorseHarnessMaker.bronzeStock,woodStock=HorseHarnessMaker.woodStock,leatherStock=HorseHarnessMaker.leatherStock,silverStock=HorseHarnessMaker.silverStock,goldStock=HorseHarnessMaker.goldStock,jewelStock=HorseHarnessMaker.jewelStock,pearlStock=HorseHarnessMaker.pearlStock,productStock=HorseHarnessMaker.productStock,numBuildings=#HorseHarnessMaker.buildings,hasMaker=HorseHarnessMaker.maker~=nil,makerName=HorseHarnessMaker.maker and HorseHarnessMaker.maker.name or "—",makerSkill=HorseHarnessMaker.maker and HorseHarnessMaker.maker.skill or 0,activeMaking=#HorseHarnessMaker.activeMaking,totalProducts=HorseHarnessMaker.totalProducts} end
return HorseHarnessMaker
